// Generate a consistent color from a string
export const stringToColor = (str: string) => {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  const h = Math.abs(hash) % 360;
  return `hsl(${h}, 70%, 85%)`; // Pastel background
};

export const stringToBorderColor = (str: string) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const h = Math.abs(hash) % 360;
    return `hsl(${h}, 80%, 40%)`; // Darker border
  };

export const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
  return new Date(date.setDate(diff));
};

export const formatDate = (date: Date): string => {
  const d = date.getDate();
  const m = date.getMonth() + 1;
  const y = date.getFullYear();
  return `${d < 10 ? '0' + d : d}/${m < 10 ? '0' + m : m}/${y}`;
};

export const formatDateForISO = (date: Date): string => {
    // Returns YYYY-MM-DD for storage/comparisons
    const offset = date.getTimezoneOffset();
    const localDate = new Date(date.getTime() - (offset*60*1000));
    return localDate.toISOString().split('T')[0];
}

export const addDays = (date: Date, days: number) => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};

export const isBookingAllowed = (targetDate: Date): { allowed: boolean; reason?: string } => {
  const today = new Date();
  const todayMonday = getMonday(today);
  const targetMonday = getMonday(targetDate);

  // Normalize times for comparison
  todayMonday.setHours(0,0,0,0);
  targetMonday.setHours(0,0,0,0);

  // 1. Past weeks -> No
  if (targetMonday.getTime() < todayMonday.getTime()) {
    return { allowed: false, reason: "Tidak boleh menempah untuk tarikh yang telah lepas." };
  }

  // 2. Current Week -> Yes, but only for future days/times technically (we'll just allow all current week for simplicity, or check day index)
  if (targetMonday.getTime() === todayMonday.getTime()) {
      // Allow booking for current week any time (or restrict to future days if needed, but user didn't specify strict day locking within current week, only "minggu semasa")
      return { allowed: true };
  }

  // 3. Next Week -> Allowed ONLY if today is Friday or later
  const nextWeekMonday = addDays(todayMonday, 7);
  if (targetMonday.getTime() === nextWeekMonday.getTime()) {
      const dayOfWeek = today.getDay(); // 0=Sun, 1=Mon, ..., 5=Fri, 6=Sat
      // Allow if Friday (5), Saturday (6), Sunday (0)
      if (dayOfWeek === 5 || dayOfWeek === 6 || dayOfWeek === 0) {
          return { allowed: true };
      } else {
          return { allowed: false, reason: "Tempahan untuk minggu hadapan hanya dibuka bermula hari Jumaat minggu ini (12.00am)." };
      }
  }

  // 4. More than 1 week ahead -> No
  if (targetMonday.getTime() > nextWeekMonday.getTime()) {
      return { allowed: false, reason: "Tempahan hanya dibuka untuk minggu semasa dan minggu hadapan (bermula Jumaat)." };
  }

  return { allowed: true };
};

export const getDayDate = (monday: Date, dayIndex: number): Date => {
    return addDays(monday, dayIndex);
}

import { API_URL } from '../constants';
import { Booking } from '../types';

export const fetchBookings = async (): Promise<Booking[]> => {
  try {
    const response = await fetch(`${API_URL}?action=get_bookings`);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Failed to fetch bookings:", error);
    return [];
  }
};

export const createBooking = async (booking: Booking): Promise<boolean> => {
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      mode: 'no-cors', // Important for Google Apps Script simple triggers sometimes
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(booking),
    });
    // With no-cors, we get an opaque response. We assume success if no network error.
    // However, the provided GAS script returns JSON. If we want to read it, we need CORS enabled on GAS.
    // The user provided script has "Access-Control-Allow-Origin": "*", so standard fetch might work.
    // Let's try standard fetch first. If that fails due to CORS preflight, we'd fallback.
    // Given the user code explicitly sets headers, we try standard first.

    return true; 
  } catch (error) {
    console.error("Failed to create booking:", error);
    return false;
  }
};

// Modified create for better error handling if CORS works
export const createBookingWithResponse = async (booking: Booking): Promise<{success: boolean, message?: string}> => {
    try {
        const response = await fetch(API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'text/plain;charset=utf-8', // Send as text to avoid options preflight issues in some GAS setups
          },
          body: JSON.stringify(booking),
        });

        const result = await response.json();
        if (result.status === 'success') {
            return { success: true };
        } else {
            return { success: false, message: result.error || 'Unknown error' };
        }
      } catch (error) {
        console.error("Failed to create booking:", error);
        return { success: false, message: "Ralat sambungan server. Sila cuba lagi." };
      }
}

